// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(actor != address(0));
        ts = bound(ts, 1, type(uint64).max - 1);

        vm.deal(actor, 10 ether);

        // First successful call at timestamp ts records it.
        vm.roll(ts);
        vm.warp(ts);
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // Second call in the SAME block/timestamp must revert: the stored
        // pastBlockTime equals ts, so block.timestamp > pastBlockTime fails.
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2);
    }
}
